commands.windows:
# Standalone example: Basic CPU and memory details as text; omits the built-in normalized hardware schema.
$ErrorActionPreference = "Stop"
Get-CimInstance Win32_ComputerSystem | ForEach-Object { '{0} {1} CPUs={2} Memory={3}' -f $_.Manufacturer, $_.Model, $_.NumberOfLogicalProcessors, $_.TotalPhysicalMemory }
